/* Minimal JSZip-compatible helper for client-side zip downloads. */
(function () {
    "use strict";

    const textEncoder = new TextEncoder();
    const crcTable = (() => {
        const table = new Uint32Array(256);
        for (let i = 0; i < 256; i += 1) {
            let c = i;
            for (let j = 0; j < 8; j += 1) {
                c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
            }
            table[i] = c >>> 0;
        }
        return table;
    })();

    function crc32(bytes) {
        let crc = 0xffffffff;
        for (let i = 0; i < bytes.length; i += 1) {
            const byte = bytes[i];
            crc = crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8);
        }
        return (crc ^ 0xffffffff) >>> 0;
    }

    function toUint8Array(content) {
        if (content instanceof Uint8Array) return content;
        if (content instanceof ArrayBuffer) return new Uint8Array(content);
        return textEncoder.encode(String(content || ""));
    }

    function writeUint16(view, offset, value) {
        view.setUint16(offset, value, true);
    }

    function writeUint32(view, offset, value) {
        view.setUint32(offset, value, true);
    }

    function buildLocalHeader(fileNameBytes, crc, size) {
        const header = new Uint8Array(30 + fileNameBytes.length);
        const view = new DataView(header.buffer);
        writeUint32(view, 0, 0x04034b50);
        writeUint16(view, 4, 20);
        writeUint16(view, 6, 0);
        writeUint16(view, 8, 0);
        writeUint16(view, 10, 0);
        writeUint16(view, 12, 0);
        writeUint32(view, 14, crc);
        writeUint32(view, 18, size);
        writeUint32(view, 22, size);
        writeUint16(view, 26, fileNameBytes.length);
        writeUint16(view, 28, 0);
        header.set(fileNameBytes, 30);
        return header;
    }

    function buildCentralHeader(fileNameBytes, crc, size, offset) {
        const header = new Uint8Array(46 + fileNameBytes.length);
        const view = new DataView(header.buffer);
        writeUint32(view, 0, 0x02014b50);
        writeUint16(view, 4, 20);
        writeUint16(view, 6, 20);
        writeUint16(view, 8, 0);
        writeUint16(view, 10, 0);
        writeUint16(view, 12, 0);
        writeUint16(view, 14, 0);
        writeUint32(view, 16, crc);
        writeUint32(view, 20, size);
        writeUint32(view, 24, size);
        writeUint16(view, 28, fileNameBytes.length);
        writeUint16(view, 30, 0);
        writeUint16(view, 32, 0);
        writeUint16(view, 34, 0);
        writeUint16(view, 36, 0);
        writeUint32(view, 38, 0);
        writeUint32(view, 42, offset);
        header.set(fileNameBytes, 46);
        return header;
    }

    function buildEndRecord(entries, centralSize, centralOffset) {
        const header = new Uint8Array(22);
        const view = new DataView(header.buffer);
        writeUint32(view, 0, 0x06054b50);
        writeUint16(view, 4, 0);
        writeUint16(view, 6, 0);
        writeUint16(view, 8, entries);
        writeUint16(view, 10, entries);
        writeUint32(view, 12, centralSize);
        writeUint32(view, 16, centralOffset);
        writeUint16(view, 20, 0);
        return header;
    }

    function concatArrays(parts) {
        const totalLength = parts.reduce((sum, part) => sum + part.length, 0);
        const merged = new Uint8Array(totalLength);
        let offset = 0;
        parts.forEach(part => {
            merged.set(part, offset);
            offset += part.length;
        });
        return merged;
    }

    class JSZip {
        constructor() {
            this._files = [];
        }

        file(name, content) {
            this._files.push({ name, content });
            return this;
        }

        async generateAsync(options = {}) {
            const parts = [];
            const centralParts = [];
            let offset = 0;

            this._files.forEach(file => {
                const fileNameBytes = textEncoder.encode(file.name);
                const data = toUint8Array(file.content);
                const crc = crc32(data);
                const localHeader = buildLocalHeader(fileNameBytes, crc, data.length);
                parts.push(localHeader, data);
                const centralHeader = buildCentralHeader(fileNameBytes, crc, data.length, offset);
                centralParts.push(centralHeader);
                offset += localHeader.length + data.length;
            });

            const centralDir = concatArrays(centralParts);
            const endRecord = buildEndRecord(this._files.length, centralDir.length, offset);
            const zipData = concatArrays([...parts, centralDir, endRecord]);

            if (options.type === "blob") {
                return new Blob([zipData], { type: "application/zip" });
            }
            return zipData;
        }
    }

    window.JSZip = JSZip;
})();
